add_action( 'rest_api_init', function () { register_rest_route( 'nadlan-dbg/v1', '/brain', array( 'methods' => 'GET', 'permission_callback' => function(){ return current_user_can('manage_options'); }, 'callback' => function () { if ( ! function_exists( 'nadlan_brain_judge' ) ) { return array( 'err' => 'brain not loaded' ); } $t0 = microtime( true ); $j = nadlan_brain_judge( '<p>היטל השבחה הוא תשלום לרשות המקומית.</p>', 'ערך אנציקלופדי: דיוק, עומק מקצועי עם מספרים והפניות לחוק, מבנה, אורך 800 מילים לפחות.' ); return array( 'ok' => ! is_wp_error( $j ), 'result' => is_wp_error( $j ) ? $j->get_error_code() : $j, 'ms' => round( ( microtime( true ) - $t0 ) * 1000 ) ); } ) ); } );